ga0X(){return"\u0627\u062e\u062a\u0631 \u0633\u062c\u0644\u064a\u0646 \u0645\u062e\u062a\u0644\u0641\u064a\u0646."},
gLG(){return"\u0646\u0641\u0633 \u0631\u0642\u0645 \u0627\u0644\u0647\u0627\u062a\u0641 \u0645\u0633\u062c\u0644"},
gLF(){return"\u0646\u0641\u0633 \u0627\u0644\u0627\u0633\u0645 \u0645\u0633\u062c\u0644"},
