gID(){return"\u0631\u0642\u0645 \u0627\u0644\u062d\u0633\u0627\u0628 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gIH(){return"\u0622\u064a\u0628\u0627\u0646 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
