ga2h(){return"\u09ab\u09be\u09a8\u09cd\u09a1 \u09a4\u09c8\u09b0\u09bf \u0995\u09b0\u09c1\u09a8"},
ga2p(){return"\u0995\u09cb\u09a8\u09cb \u0995\u09be\u09b8\u09cd\u099f\u09cb\u09a1\u09bf\u09af\u09bc\u09be\u09a8 \u09a8\u09bf\u09af\u09c1\u0995\u09cd\u09a4 \u0995\u09b0\u09be \u09b9\u09af\u09bc\u09a8\u09bf"},
